-- APPLIED RECEIPT: production transaction 1813, 18 November 2026. DO NOT RERUN.
-- Misfits hard no-21:00 from 19 November on both nights; Wednesday Umoja exception.
-- Ten unplayed fixture rows swap slots; opponents, dates and all results remain unchanged.
-- Organiser authorised future repairs while preserving every 18 November fixture.
BEGIN;
SET LOCAL lock_timeout='5s';SET LOCAL statement_timeout='30s';
LOCK TABLE public.fixtures,public.result_versions,public.teams,public.team_fixture_notes,public.team_kickoff_preferences,public.fixture_change_sets IN SHARE ROW EXCLUSIVE MODE;
CREATE TEMP TABLE mis_fixtures_before ON COMMIT DROP AS SELECT * FROM public.fixtures;
CREATE TEMP TABLE mis_results_before ON COMMIT DROP AS SELECT * FROM public.result_versions;
CREATE TEMP TABLE mis_teams_before ON COMMIT DROP AS SELECT * FROM public.teams;
CREATE TEMP TABLE mis_notes_before ON COMMIT DROP AS SELECT * FROM public.team_fixture_notes;
CREATE TEMP TABLE mis_preferences_before ON COMMIT DROP AS SELECT * FROM public.team_kickoff_preferences;
CREATE TEMP TABLE mis_audit_before ON COMMIT DROP AS SELECT * FROM public.admin_audit_log;
CREATE TEMP TABLE mis_baseline ON COMMIT DROP AS SELECT * FROM jsonb_populate_recordset(null::public.fixtures,'[{"id": "fbec2d26-3007-4521-aa4e-e461fd5b1832", "competition_season_id": "62ce7ec9-459e-4acf-bec5-c6734a3199ef", "round_number": 18, "match_date": "2027-03-01", "kickoff_time": "19:40:00", "court": 2, "home_team_id": "e5b8d7c3-89e1-430a-94b4-afd7b42cbe43", "away_team_id": "57b0b3f9-24a5-4ea7-9e1b-fd3faa90891c", "publication_state": "published", "schedule_status": "scheduled", "schedule_version": 11, "updated_at": "2026-11-16T13:34:19.698625+00:00"}, {"id": "da5c990a-28e8-5395-a888-816ed5ab459c", "competition_season_id": "62ce7ec9-459e-4acf-bec5-c6734a3199ef", "round_number": 18, "match_date": "2027-03-01", "kickoff_time": "21:00:00", "court": 2, "home_team_id": "8434b3b9-091d-4d8b-ab29-f857807d1c3b", "away_team_id": "8464062e-5897-4573-a075-d283236dd36c", "publication_state": "published", "schedule_status": "scheduled", "schedule_version": 8, "updated_at": "2026-11-10T12:15:57.93124+00:00"}, {"id": "bdd6ec98-bf6f-4dc1-ac7d-b1e1d1991d9d", "competition_season_id": "62ce7ec9-459e-4acf-bec5-c6734a3199ef", "round_number": 23, "match_date": "2027-04-19", "kickoff_time": "19:40:00", "court": 1, "home_team_id": "8464062e-5897-4573-a075-d283236dd36c", "away_team_id": "544ff92b-0753-4e4f-9feb-bdcdf9c74a98", "publication_state": "published", "schedule_status": "scheduled", "schedule_version": 2, "updated_at": "2026-10-31T08:45:07.945244+00:00"}, {"id": "ed449f46-1446-4fa4-8a55-cab5431075e6", "competition_season_id": "62ce7ec9-459e-4acf-bec5-c6734a3199ef", "round_number": 23, "match_date": "2027-04-19", "kickoff_time": "21:00:00", "court": 1, "home_team_id": "8434b3b9-091d-4d8b-ab29-f857807d1c3b", "away_team_id": "0ad2ddbd-80e1-40f5-bb80-2e756a3d9419", "publication_state": "published", "schedule_status": "scheduled", "schedule_version": 7, "updated_at": "2026-11-05T18:28:52.669443+00:00"}, {"id": "7a9cdfa6-77cb-4aae-91de-0e0408f32d23", "competition_season_id": "62ce7ec9-459e-4acf-bec5-c6734a3199ef", "round_number": 26, "match_date": "2027-05-10", "kickoff_time": "19:40:00", "court": 1, "home_team_id": "544ff92b-0753-4e4f-9feb-bdcdf9c74a98", "away_team_id": "44d7e359-957a-4b38-8a0a-40b698d609c9", "publication_state": "published", "schedule_status": "scheduled", "schedule_version": 4, "updated_at": "2026-11-16T13:34:19.698625+00:00"}, {"id": "d8aa201e-3fb9-4baa-962d-651db2094c10", "competition_season_id": "62ce7ec9-459e-4acf-bec5-c6734a3199ef", "round_number": 26, "match_date": "2027-05-10", "kickoff_time": "21:00:00", "court": 2, "home_team_id": "e5b8d7c3-89e1-430a-94b4-afd7b42cbe43", "away_team_id": "8434b3b9-091d-4d8b-ab29-f857807d1c3b", "publication_state": "published", "schedule_status": "scheduled", "schedule_version": 4, "updated_at": "2026-10-31T08:45:07.945244+00:00"}, {"id": "fd77a8cc-b1cf-49ed-b43e-2aa45be9c308", "competition_season_id": "be008d39-f175-45c1-a232-2148d84b1cf9", "round_number": 10, "match_date": "2027-01-13", "kickoff_time": "20:20:00", "court": 2, "home_team_id": "435af587-f6ea-5030-a097-94ad466481c2", "away_team_id": "99d1aedc-409b-4495-b32c-c874ec5958e0", "publication_state": "published", "schedule_status": "scheduled", "schedule_version": 4, "updated_at": "2026-10-31T08:45:07.945244+00:00"}, {"id": "cfca92d9-beb0-4986-9ca3-24c0de8ccb78", "competition_season_id": "be008d39-f175-45c1-a232-2148d84b1cf9", "round_number": 10, "match_date": "2027-01-13", "kickoff_time": "21:00:00", "court": 2, "home_team_id": "2c8b11cb-0809-475a-a9e8-d39834c41ccb", "away_team_id": "92b8f805-41b1-446a-b843-6f7cc7083e90", "publication_state": "published", "schedule_status": "scheduled", "schedule_version": 6, "updated_at": "2026-10-31T08:45:07.945244+00:00"}, {"id": "98dbc672-3967-480c-95bc-8f90f7f1dbdb", "competition_season_id": "be008d39-f175-45c1-a232-2148d84b1cf9", "round_number": 28, "match_date": "2027-05-19", "kickoff_time": "19:40:00", "court": 2, "home_team_id": "2c8b11cb-0809-475a-a9e8-d39834c41ccb", "away_team_id": "b3be09fa-1f9e-4501-be80-ae0346804d31", "publication_state": "published", "schedule_status": "scheduled", "schedule_version": 2, "updated_at": "2026-10-31T08:45:07.945244+00:00"}, {"id": "5c84aa02-d325-4d75-b02c-1b9a33943cf6", "competition_season_id": "be008d39-f175-45c1-a232-2148d84b1cf9", "round_number": 28, "match_date": "2027-05-19", "kickoff_time": "21:00:00", "court": 1, "home_team_id": "92b8f805-41b1-446a-b843-6f7cc7083e90", "away_team_id": "8f0b3cd6-a819-411e-b08c-b57a3c9367fe", "publication_state": "published", "schedule_status": "scheduled", "schedule_version": 2, "updated_at": "2026-10-31T08:45:07.945244+00:00"}]'::jsonb);
CREATE TEMP TABLE mis_target ON COMMIT DROP AS SELECT * FROM jsonb_to_recordset('[{"id": "fbec2d26-3007-4521-aa4e-e461fd5b1832", "kickoff_time": "21:00:00", "court": 2}, {"id": "da5c990a-28e8-5395-a888-816ed5ab459c", "kickoff_time": "19:40:00", "court": 2}, {"id": "bdd6ec98-bf6f-4dc1-ac7d-b1e1d1991d9d", "kickoff_time": "21:00:00", "court": 1}, {"id": "ed449f46-1446-4fa4-8a55-cab5431075e6", "kickoff_time": "19:40:00", "court": 1}, {"id": "7a9cdfa6-77cb-4aae-91de-0e0408f32d23", "kickoff_time": "21:00:00", "court": 2}, {"id": "d8aa201e-3fb9-4baa-962d-651db2094c10", "kickoff_time": "19:40:00", "court": 1}, {"id": "fd77a8cc-b1cf-49ed-b43e-2aa45be9c308", "kickoff_time": "21:00:00", "court": 2}, {"id": "cfca92d9-beb0-4986-9ca3-24c0de8ccb78", "kickoff_time": "20:20:00", "court": 2}, {"id": "98dbc672-3967-480c-95bc-8f90f7f1dbdb", "kickoff_time": "21:00:00", "court": 1}, {"id": "5c84aa02-d325-4d75-b02c-1b9a33943cf6", "kickoff_time": "19:40:00", "court": 2}]'::jsonb) AS x(id uuid,kickoff_time time,court integer);
DO $$BEGIN
 IF (SELECT count(*) FROM mis_target)<>10 OR EXISTS(SELECT 1 FROM mis_baseline b LEFT JOIN public.fixtures f USING(id) WHERE row(b.competition_season_id,b.round_number,b.match_date,b.kickoff_time,b.court,b.home_team_id,b.away_team_id,b.publication_state,b.schedule_status,b.schedule_version,b.updated_at) IS DISTINCT FROM row(f.competition_season_id,f.round_number,f.match_date,f.kickoff_time,f.court,f.home_team_id,f.away_team_id,f.publication_state,f.schedule_status,f.schedule_version,f.updated_at)) THEN RAISE EXCEPTION 'Fixture baseline changed or already applied';END IF;
 IF EXISTS(SELECT 1 FROM mis_baseline WHERE match_date+kickoff_time <= now() AT TIME ZONE 'Australia/Melbourne') THEN RAISE EXCEPTION 'Affected playing slot has started; review before rescheduling';END IF;
 IF EXISTS(SELECT 1 FROM public.result_versions WHERE fixture_id IN(SELECT id FROM mis_target)) THEN RAISE EXCEPTION 'Affected result work exists';END IF;
 IF EXISTS(SELECT 1 FROM public.fixture_change_sets WHERE competition_season_id IN(SELECT competition_season_id FROM mis_baseline) AND status IN('draft','pending_review')) THEN RAISE EXCEPTION 'Pending fixture work';END IF;
 IF NOT EXISTS(SELECT 1 FROM public.teams WHERE id='8434b3b9-091d-4d8b-ab29-f857807d1c3b' AND name='Misfits' AND status='active' AND profile_version=2 AND updated_at='2026-10-13T01:55:32.481516+00:00'::timestamptz) THEN RAISE EXCEPTION 'Misfits profile baseline changed';END IF;
 IF NOT EXISTS(SELECT 1 FROM public.teams WHERE id='92b8f805-41b1-446a-b843-6f7cc7083e90' AND name='Misfits' AND status='active' AND profile_version=2 AND updated_at='2026-10-13T01:59:21.938786+00:00'::timestamptz) THEN RAISE EXCEPTION 'Misfits profile baseline changed';END IF;
 IF EXISTS(SELECT 1 FROM public.team_kickoff_preferences WHERE team_id IN('8434b3b9-091d-4d8b-ab29-f857807d1c3b','92b8f805-41b1-446a-b843-6f7cc7083e90')) THEN RAISE EXCEPTION 'Misfits preference baseline changed';END IF;
END $$;
UPDATE public.fixtures SET publication_state='draft' WHERE id IN(SELECT id FROM mis_target);
UPDATE public.fixtures f SET kickoff_time=p.kickoff_time,court=p.court,publication_state='published' FROM mis_target p WHERE p.id=f.id;
UPDATE public.teams SET profile_version=profile_version+1 WHERE id IN('8434b3b9-091d-4d8b-ab29-f857807d1c3b','92b8f805-41b1-446a-b843-6f7cc7083e90');
INSERT INTO public.team_kickoff_preferences(team_id,kickoff_time,classification)
SELECT t.id,p.tm::time,'required' FROM public.teams t CROSS JOIN(VALUES('19:00'),('19:40'),('20:20'))p(tm) WHERE t.id IN('8434b3b9-091d-4d8b-ab29-f857807d1c3b','92b8f805-41b1-446a-b843-6f7cc7083e90');
INSERT INTO public.team_fixture_notes(team_id,notes)
SELECT id,'Current organiser rule, 18 November 2026: Effective from 19 November 2026: Misfits cannot play at 21:00 (hard). All fixtures on 18 November 2026 remain exactly as published by explicit organiser instruction. General allowed times: 19:00, 19:40, 20:20. ' || CASE WHEN id='92b8f805-41b1-446a-b843-6f7cc7083e90' THEN 'EXPLICIT WEDNESDAY EXCEPTION: against Umoja Stars, Misfits must play at 21:00 because Umoja always plays then. This exception does not allow 21:00 against any other opponent. ' ELSE 'No Monday opponent exception. ' END || 'This supersedes earlier any-time availability.' FROM public.teams WHERE id IN('8434b3b9-091d-4d8b-ab29-f857807d1c3b','92b8f805-41b1-446a-b843-6f7cc7083e90')
ON CONFLICT(team_id) DO UPDATE SET notes=excluded.notes || E'\n\nEarlier scheduling context (superseded where conflicting):\n' || public.team_fixture_notes.notes;
DO $$BEGIN
 IF EXISTS(SELECT 1 FROM mis_fixtures_before b FULL JOIN public.fixtures f USING(id) WHERE CASE WHEN b.id IN(SELECT id FROM mis_target) THEN (to_jsonb(b)-'kickoff_time'-'court'-'publication_state'-'schedule_version'-'updated_at') IS DISTINCT FROM (to_jsonb(f)-'kickoff_time'-'court'-'publication_state'-'schedule_version'-'updated_at') OR f.publication_state<>'published' OR f.schedule_version<>b.schedule_version+2 OR NOT EXISTS(SELECT 1 FROM mis_target p WHERE p.id=f.id AND row(p.kickoff_time,p.court)=row(f.kickoff_time,f.court)) ELSE to_jsonb(b) IS DISTINCT FROM to_jsonb(f) END) THEN RAISE EXCEPTION 'Unexpected fixture change';END IF;
 IF EXISTS(SELECT 1 FROM mis_results_before b FULL JOIN public.result_versions t USING(id) WHERE to_jsonb(b) IS DISTINCT FROM to_jsonb(t)) THEN RAISE EXCEPTION 'Results changed';END IF;
 IF EXISTS(SELECT 1 FROM mis_teams_before b FULL JOIN public.teams t USING(id) WHERE CASE WHEN b.id IN('8434b3b9-091d-4d8b-ab29-f857807d1c3b','92b8f805-41b1-446a-b843-6f7cc7083e90') THEN (to_jsonb(b)-'profile_version'-'updated_at') IS DISTINCT FROM (to_jsonb(t)-'profile_version'-'updated_at') OR t.profile_version<>b.profile_version+1 ELSE to_jsonb(b) IS DISTINCT FROM to_jsonb(t) END) THEN RAISE EXCEPTION 'Unexpected team change';END IF;
 IF EXISTS(SELECT 1 FROM mis_notes_before b FULL JOIN public.team_fixture_notes t USING(team_id) WHERE coalesce(b.team_id,t.team_id) NOT IN('8434b3b9-091d-4d8b-ab29-f857807d1c3b','92b8f805-41b1-446a-b843-6f7cc7083e90') AND to_jsonb(b) IS DISTINCT FROM to_jsonb(t)) THEN RAISE EXCEPTION 'Unrelated notes changed';END IF;
 IF EXISTS(SELECT 1 FROM mis_preferences_before b FULL JOIN public.team_kickoff_preferences t USING(id) WHERE coalesce(b.team_id,t.team_id) NOT IN('8434b3b9-091d-4d8b-ab29-f857807d1c3b','92b8f805-41b1-446a-b843-6f7cc7083e90') AND to_jsonb(b) IS DISTINCT FROM to_jsonb(t)) THEN RAISE EXCEPTION 'Unrelated preferences changed';END IF;
 IF (SELECT count(*) FROM public.team_kickoff_preferences WHERE team_id IN('8434b3b9-091d-4d8b-ab29-f857807d1c3b','92b8f805-41b1-446a-b843-6f7cc7083e90') AND classification='required' AND kickoff_time IN('19:00','19:40','20:20'))<>6 THEN RAISE EXCEPTION 'Misfits preferences failed';END IF;
 IF EXISTS(SELECT 1 FROM public.fixtures f WHERE f.publication_state='published' AND f.schedule_status='scheduled' AND f.match_date>='2026-11-19' AND f.kickoff_time='21:00' AND (f.home_team_id IN('8434b3b9-091d-4d8b-ab29-f857807d1c3b','92b8f805-41b1-446a-b843-6f7cc7083e90') OR f.away_team_id IN('8434b3b9-091d-4d8b-ab29-f857807d1c3b','92b8f805-41b1-446a-b843-6f7cc7083e90')) AND NOT(f.competition_season_id='be008d39-f175-45c1-a232-2148d84b1cf9' AND 'bafe147f-c3ac-4285-8159-f8e13a06e067' IN(f.home_team_id,f.away_team_id))) THEN RAISE EXCEPTION 'Misfits still has an unapproved future 21:00 game';END IF;
 IF EXISTS(SELECT 1 FROM mis_audit_before b LEFT JOIN public.admin_audit_log t USING(id) WHERE to_jsonb(b) IS DISTINCT FROM to_jsonb(t)) THEN RAISE EXCEPTION 'Existing audit changed';END IF;
END $$;
SELECT txid_current() AS transaction_id,(SELECT count(*) FROM mis_target) AS changed_fixtures;
COMMIT;
